metadata.er-schema:
{
  "title": "looply · 类目管理（Collection）实体关系图",
  "version": "v1.0 · 2026-06-04",
  "tables": [
    {
      "name": "collection",
      "comment": "前台商品分组",
      "columns": [
        {
          "name": "fc_id",
          "comment": "分组ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "name_en",
          "comment": "英文名称",
          "constraint": ""
        },
        {
          "name": "name_zh",
          "comment": "中文名称",
          "constraint": ""
        },
        {
          "name": "url_slug",
          "comment": "URL路径段",
          "constraint": "UNIQUE"
        },
        {
          "name": "icon_url",
          "comment": "入口图URL",
          "constraint": ""
        },
        {
          "name": "banner_url",
          "comment": "Banner图URL",
          "constraint": ""
        },
        {
          "name": "description",
          "comment": "描述（富文本）",
          "constraint": ""
        },
        {
          "name": "h1_title",
          "comment": "页面H1标题",
          "constraint": ""
        },
        {
          "name": "seo_title",
          "comment": "Meta Title",
          "constraint": ""
        },
        {
          "name": "seo_description",
          "comment": "Meta Desc",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "选品类型 rule/manual",
          "constraint": ""
        },
        {
          "name": "rule_config",
          "comment": "自动选品规则JSON",
          "constraint": ""
        },
        {
          "name": "default_sort_key",
          "comment": "默认排序",
          "constraint": ""
        },
        {
          "name": "display_mode",
          "comment": "展示模式",
          "constraint": ""
        },
        {
          "name": "products_per_page",
          "comment": "每页商品数",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/archived",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "is_system",
          "comment": "是否系统级",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "is_system=TRUE 为系统级（All Products），不可删除/下架"
    },
    {
      "name": "fc_manual_product",
      "comment": "手动选品关联",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "商品listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "sort_order",
          "comment": "位置（Position）",
          "constraint": ""
        },
        {
          "name": "pinned",
          "comment": "是否固定位置",
          "constraint": ""
        },
        {
          "name": "is_hidden",
          "comment": "是否隐藏",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "添加时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, listing_id)；商品下架后保留记录，is_hidden 可临时隐藏"
    },
    {
      "name": "fc_hidden_product",
      "comment": "自动选品排除记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "listing_id",
          "comment": "被排除的listingID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "created_at",
          "comment": "排除时间",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, listing_id)；商品下架时同步清除此记录（pin不持久化）"
    },
    {
      "name": "filter_dimension",
      "comment": "筛选维度（全局池）",
      "columns": [
        {
          "name": "dimension_id",
          "comment": "维度ID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_name_en",
          "comment": "英文名称",
          "constraint": ""
        },
        {
          "name": "dimension_name_zh",
          "comment": "中文名称",
          "constraint": ""
        },
        {
          "name": "dimension_type",
          "comment": "展示类型 checkbox/range/color_swatch/size_grid/radio/search_list",
          "constraint": ""
        },
        {
          "name": "source_type",
          "comment": "数据源类型 attribute/brand/series/price/condition(A/B/C)/size_system",
          "constraint": ""
        },
        {
          "name": "source_config",
          "comment": "数据源特有配置JSON",
          "constraint": ""
        },
        {
          "name": "value_mapping",
          "comment": "值归一化规则JSON",
          "constraint": ""
        },
        {
          "name": "min_fill_rate",
          "comment": "最低填充率阈值",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "source_type=attribute 时通过 filter_dimension_source 关联属性"
    },
    {
      "name": "filter_dimension_source",
      "comment": "维度-属性多源绑定",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "dimension_id",
          "comment": "所属筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "attribute_id",
          "comment": "关联属性定义ID",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "priority",
          "comment": "多源优先级",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(dimension_id, attribute_id)；仅 source_type=attribute 的维度使用"
    },
    {
      "name": "fc_filter_config",
      "comment": "Collection筛选配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "fc_id",
          "comment": "所属分组",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "dimension_id",
          "comment": "引用的筛选维度",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "display_name_en",
          "comment": "覆盖展示名称",
          "constraint": ""
        },
        {
          "name": "sort_order",
          "comment": "筛选面板排序",
          "constraint": ""
        },
        {
          "name": "is_collapsible",
          "comment": "是否可折叠",
          "constraint": ""
        },
        {
          "name": "default_expanded",
          "comment": "默认是否展开",
          "constraint": ""
        },
        {
          "name": "is_quick_filter",
          "comment": "是否Quick Filter",
          "constraint": ""
        },
        {
          "name": "quick_filter_label",
          "comment": "Quick Filter标签",
          "constraint": ""
        },
        {
          "name": "quick_filter_preset",
          "comment": "Quick Filter预设条件JSON",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "状态 active/inactive",
          "constraint": ""
        }
      ],
      "note": "UNIQUE(fc_id, dimension_id)；每个Collection独立配置引用哪些维度"
    },
    {
      "name": "listing",
      "comment": "商品上架记录",
      "columns": [
        {
          "name": "listing_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "attribute_def",
      "comment": "属性定义",
      "columns": [
        {
          "name": "attribute_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "外部引用，字段由商品系统维护，不在本模块展开"
    },
    {
      "name": "brand",
      "comment": "品牌",
      "columns": [
        {
          "name": "brand_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=brand 时的数据来源（逻辑引用）"
    },
    {
      "name": "series",
      "comment": "系列",
      "columns": [
        {
          "name": "series_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=series 时的数据来源（逻辑引用）"
    },
    {
      "name": "size_system",
      "comment": "尺码体系",
      "columns": [
        {
          "name": "size_system_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "filter_dimension source_type=size_system 时的数据来源（逻辑引用）"
    },
    {
      "name": "backend_category",
      "comment": "后台类目",
      "columns": [
        {
          "name": "category_id",
          "comment": "（商品系统）",
          "constraint": "PRIMARY KEY"
        }
      ],
      "note": "rule_config JSON 条件字段引用（非FK），不作为筛选维度数据源"
    }
  ],
  "relations": [
    {
      "from": "collection",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "手动选品",
      "color": "#2D72B8",
      "penwidth": 1.8
    },
    {
      "from": "collection",
      "to": "fc_hidden_product",
      "type": "1:N",
      "label": "排除记录",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "collection",
      "to": "fc_filter_config",
      "type": "1:N",
      "label": "筛选配置",
      "color": "#2D72B8",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "fc_filter_config",
      "type": "1:N",
      "label": "被引用",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "filter_dimension",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "多源绑定",
      "color": "#2E7D4F",
      "penwidth": 1.4
    },
    {
      "from": "listing",
      "to": "fc_manual_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "listing",
      "to": "fc_hidden_product",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "attribute_def",
      "to": "filter_dimension_source",
      "type": "1:N",
      "label": "FK",
      "color": "#9E9E9E",
      "penwidth": 1.0
    },
    {
      "from": "brand",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=brand",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "series",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=series",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "size_system",
      "to": "filter_dimension",
      "type": "",
      "label": "source_type=size_system",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    },
    {
      "from": "backend_category",
      "to": "collection",
      "type": "",
      "label": "rule_config 条件字段\n（JSON引用，非FK）",
      "color": "#BDBDBD",
      "penwidth": 0.8,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "R-01": "Collection 无层级嵌套，扁平结构，导航层级由 Navigation 模块承载",
    "R-02": "商品粒度为 listing 级别，不按 SPU 聚合",
    "R-03": "自动选品/手动选品两种模式互斥（source_type=rule 或 manual）",
    "R-04": "All Products 为系统级 Collection（is_system=TRUE），不可删除、不可下架、rule_config 为空（全量）",
    "R-05": "自动选品商品下架时同步清除 fc_hidden_product 中的对应 pin 记录（不持久化）",
    "R-06": "手动选品商品下架后 fc_manual_product 记录保留，is_hidden=TRUE，商品重新上架后恢复",
    "R-07": "backend_category 不作为 filter_dimension 的 source_type，仅用于 rule_config 条件字段",
    "R-08": "filter_dimension source_type=attribute 时，通过 filter_dimension_source 支持多个 attribute_def 绑定到同一维度",
    "R-09": "后台商品列表顺序 = 前端实际展示顺序（WYSIWYG），sort_order 字段即最终渲染位置",
    "R-10": "Quick Filter 商品数为 0 时前端自动隐藏该 Chip（实时判断）",
    "R-11": "filter_dimension 填充率低于 min_fill_rate 时前台自动隐藏该维度分组（每日 cron 更新）"
  }
}
